import React, { useState } from "react";
import InputForm from "./components/InputForm";
import ResultDisplay from "./components/ResultDisplay";
import PerformanceChart from "./charts/PerformanceChart";
import DNAViewer from "./components/DNAViewer";
import { analyzeDNA } from "./services/api";
import "./App.css";

function App() {
  const [dna, setDna] = useState("");
  const [pattern, setPattern] = useState("");
  const [result, setResult] = useState(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const handleAnalyze = async () => {
    const normalizedDna = (dna || "").trim().toUpperCase();
    const normalizedPattern = (pattern || "").trim().toUpperCase();

    if (!normalizedDna) {
      alert("DNA not loaded!");
      return;
    }

    if (!normalizedPattern) {
      alert("Enter pattern!");
      return;
    }

    setIsAnalyzing(true);

    try {
      const response = await analyzeDNA(normalizedDna, normalizedPattern);
      setResult(response);
    } catch (error) {
      alert(
        error?.response?.data?.message ||
          "Unable to analyze DNA. Please check the backend connection."
      );
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="app-shell">
      <div className="app-container">
        <header className="hero-card">
          <p className="eyebrow">DNA Pattern Matching</p>
          <h1 className="page-title">DNA Analysis Dashboard</h1>
          <p className="page-subtitle">
            Upload a FASTA file or paste DNA manually, run the matching
            algorithms, compare execution time, and inspect highlighted matches.
          </p>
        </header>

        <div className="card">
          <InputForm
            dna={dna}
            pattern={pattern}
            setDna={setDna}
            setPattern={setPattern}
            onAnalyze={handleAnalyze}
            isAnalyzing={isAnalyzing}
          />
        </div>

        {result && (
          <>
            <div className="card">
              <ResultDisplay result={result} />
            </div>

            <div className="card">
              <PerformanceChart time={result.time} />
            </div>

            <div className="card">
              <DNAViewer
                dna={dna}
                matches={result?.results?.kmp || []}
                pattern={pattern}
              />
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default App;
