export default function ResultDisplay({ result }) {
  if (!result || !result.results) {
    return null;
  }

  const entries = [
    ["naive", "Naive"],
    ["kmp", "KMP"],
    ["rabin", "Rabin-Karp"],
    ["hamming", "Hamming"]
  ];

  return (
    <section>
      <div className="section-heading">
        <h2>Match Results</h2>
        <p>Readable output for each algorithm without exposing raw JSON.</p>
      </div>

      <div className="result-grid">
        {entries.map(([key, label]) => {
          const matches = Array.isArray(result.results[key]) ? result.results[key] : [];

          return (
            <article key={key} className="result-card">
              <h3>{label}</h3>
              <p className="result-line">
                {label} {"\u2192"} {matches.length > 0 ? matches.join(", ") : "No match found"}
              </p>
            </article>
          );
        })}
      </div>
    </section>
  );
}
